#!/usr/bin/env bash
# Token Harbor account registrar - launcher for macOS and Linux.
# This single file contains the whole tool.
set -u

if ! command -v node >/dev/null 2>&1; then
  cat <<'MSG'

This tool needs Node.js to run, and it is not installed on this computer.

Node.js is a free program that runs this tool. You install it once.

  Easiest:  open https://nodejs.org and click the green "LTS" button,
            then run the installer.
  Linux:    sudo apt install nodejs npm     (Debian/Ubuntu)
            sudo dnf install nodejs npm     (Fedora)
  Or:       brew install node               (macOS, if you use Homebrew)

After that, run this script again.
MSG
  exit 1
fi

NODE_MAJOR="$(node -p 'process.versions.node.split(".")[0]' 2>/dev/null || echo 0)"
if [ "${NODE_MAJOR:-0}" -lt 18 ]; then
  cat <<MSG

This tool needs Node.js version 18 or newer.
This computer has version $(node -v 2>/dev/null).

Install the "LTS" version from https://nodejs.org over the one you have,
then run this script again.
MSG
  exit 1
fi

APP_DIR="${TH_HOME:-$HOME/.tokenharbor-registrar}"
mkdir -p "$APP_DIR"

# write the embedded script out fresh, so the newest version always runs
awk 'f{print} /^__TH_PAYLOAD_B64__$/{f=1}' "$0" | base64 -d > "$APP_DIR/run_headless.js.tmp" || {
  echo
  echo This file looks damaged - the part inside it could not be read.
  echo Download the script again and run it once more.
  exit 1
}
mv "$APP_DIR/run_headless.js.tmp" "$APP_DIR/run_headless.js"

if [ ! -d "$APP_DIR/node_modules/playwright" ]; then
  if ! command -v npm >/dev/null 2>&1; then
    cat <<'MSG'

This tool needs the "npm" command, which comes with Node.js, and it is missing.

Reinstall the "LTS" version from https://nodejs.org, then run this script again.
MSG
    exit 1
  fi
  echo
  echo "One-time setup: downloading a small helper (about 40 MB). This runs once."
  echo
  # Only one launcher may install at a time: two starting together on a fresh computer would
  # both write into the same node_modules. mkdir is the atomic "who got here first" primitive.
  if mkdir "$APP_DIR/.npm-lock" 2>/dev/null; then
    ( cd "$APP_DIR" && npm install --no-fund --no-audit --loglevel=error playwright )
    rmdir "$APP_DIR/.npm-lock"
  else
    echo "Another copy of this tool is fetching it right now; waiting for that one."
    i=0
    while [ "$i" -lt 150 ] && [ ! -d "$APP_DIR/node_modules/playwright" ]; do
      i=$((i + 1))
      sleep 2
    done
  fi
  if [ ! -d "$APP_DIR/node_modules/playwright" ]; then
    cat <<'MSG'

The download failed. This is almost always a temporary internet problem.

Check that this computer is online, then run this script again.
MSG
    exit 1
  fi
  echo
  echo "Setup finished."
fi

# Anything the operator types after the script name is passed straight through, so the launcher can
# do the whole tool's work: "this-file --warp down" closes the tunnel, "this-file --bulk 5 --now"
# runs the engine. No argument at all means the wizard, which is what the file is for.
export TH_SELF="$0"
if [ "$#" -eq 0 ]; then set -- --wizard; fi
exec node "$APP_DIR/run_headless.js" "$@"
